class DecisionClient:
    def __init__(
        self,
        *,
        budget: Budget,
        actions: Mapping[str, Any],
        api_key: str | None = None,
        timeout_s: float = 5.0,
        http_client: httpx.AsyncClient | None = None,
        max_input_tokens: int = 8192,
        env_path: str | Path = ".env",
    ) -> None:
        self.budget = budget
        self.api_key = api_key or load_api_key(env_path)
        self.criteria = {}
        for action_id, action in actions.items():
            description = action if isinstance(action, str) else (
                action.get("description") if isinstance(action, Mapping) else getattr(action, "description", None)
            )
            if not isinstance(description, str) or not description:
                raise ValueError(f"Missing description for action {action_id}")
            self.criteria[action_id] = description
        if not self.criteria:
            raise ValueError("The decision action menu cannot be empty")
        self.timeout_s = timeout_s
        self.max_input_tokens = max_input_tokens
        self._owns_client = http_client is None
        self.http_client = http_client or httpx.AsyncClient(
            timeout=timeout_s, follow_redirects=False, transport=httpx.AsyncHTTPTransport(retries=0)
        )

    async def __aenter__(self) -> DecisionClient:
        return self

    async def __aexit__(self, *_):
        if self._owns_client:
            await self.http_client.aclose()

    async def decide(self, route: Mapping[str, Any], observation: Mapping[str, Any]) -> dict[str, Any]:
        requested_model = route["model"]
        requested_provider = route["provider"]
        payload = {
            "model": requested_model,
            "state": observation,
            "questions": {"control": {
                "type": "choice", "instructions": DRIVING_INSTRUCTIONS, "criteria": self.criteria,
            }},
            "provider": {"only": [requested_provider], "allow_fallbacks": False},
        }
        encoded = json.dumps(payload, ensure_ascii=False, separators=(",", ":"), allow_nan=False).encode()
        # UTF-8 bytes plus framing conservatively bound text tokens without relying
        # on an incompatible tokenizer. Reject oversized observations before spend.
        if len(encoded) + 512 > self.max_input_tokens:
            raise ValueError("Decision request exceeds the configured conservative input token ceiling")
        route_input_limit = route.get("max_prompt_tokens") or route.get("context_length")
        if route_input_limit and self.max_input_tokens > int(route_input_limit):
            raise ValueError("Configured input token ceiling exceeds the selected route context")
        max_output = int(route.get("max_completion_tokens") or route.get("context_length") or 1_000_000)
        input_price = _nonnegative(route["price_input_per_token"], "input token price")
        output_price = _nonnegative(route["price_output_per_token"], "output token price")
        request_price = _nonnegative(route.get("price_per_request", 0), "request price")
        reservation_cost = self.max_input_tokens * input_price + max_output * output_price + request_price
        reservation = self.budget.reserve(
            reservation_cost, self.max_input_tokens + max_output,
            model=requested_model, provider=requested_provider,
        )
        record = {
            "ok": False, "action": None,
            "requested_model": requested_model, "requested_provider": requested_provider,
            "resolved_model": route.get("resolved_model"),
            "model": None, "provider": None, "id": None,
            "request_started_ns": time.perf_counter_ns(), "response_received_ns": None,
            "latency_ms": None, "usage": {}, "cost": None, "cost_source": "reservation",
            "error": None, "reservation_id": reservation,
            "payload_bytes": len(encoded), "input_token_ceiling": self.max_input_tokens,
        }
        reported_cost = None
        reported_tokens = None
        try:
            response = await self.http_client.post(
                DECISIONS_URL,
                content=encoded,
                headers={"Authorization": f"Bearer {self.api_key}", "Content-Type": "application/json"},
                timeout=self.timeout_s,
            )
            record["response_received_ns"] = time.perf_counter_ns()
            record["http_status"] = response.status_code
            try:
                result = response.json()
            except ValueError:
                result = {}
            if not isinstance(result, dict):
                result = {}
            usage = result.get("usage") or (result.get("metadata") or {}).get("usage") or {}
            if not isinstance(usage, dict):
                usage = {}
            record.update({"model": result.get("model"), "provider": result.get("provider"),
                           "id": result.get("id"), "usage": usage})
            raw_cost = usage.get("cost", result.get("cost"))
            if raw_cost is not None:
                try:
                    reported_cost = _nonnegative(raw_cost, "response cost")
                    record["cost_source"] = "reported"
                except ValueError:
                    pass
            input_tokens, output_tokens = usage.get("input_tokens"), usage.get("output_tokens")
            if (isinstance(input_tokens, int) and not isinstance(input_tokens, bool) and input_tokens >= 0
                    and isinstance(output_tokens, int) and not isinstance(output_tokens, bool) and output_tokens >= 0):
                reported_tokens = input_tokens + output_tokens
            if response.is_error:
                record["error"] = f"http_{response.status_code}"
            elif result.get("error"):
                record["error"] = "api_error"
            elif result.get("refusal"):
                record["error"] = "refusal"
            else:
                answers = result.get("answers")
                answer = answers.get("control") if isinstance(answers, dict) else None
                action = answer.get("choice") if isinstance(answer, dict) else None
                if not isinstance(action, str) or action not in self.criteria:
                    record["error"] = "invalid_action"
                elif not isinstance(result.get("model"), str) or not isinstance(result.get("provider"), str):
                    record["error"] = "missing_response_identity"
                elif result["provider"].casefold() != str(route.get("provider_name", requested_provider)).casefold():
                    record["error"] = "unexpected_provider"
                elif result["model"] not in {requested_model, route.get("resolved_model", requested_model)}:
                    record["error"] = "unexpected_model"
                else:
                    record["ok"] = True
                    record["action"] = action
        except asyncio.CancelledError:
            record["error"] = "cancelled"
            raise
        except httpx.TimeoutException:
            record["error"] = "timeout"
        except httpx.HTTPError:
            record["error"] = "transport_error"
        finally:
            record["response_received_ns"] = record["response_received_ns"] or time.perf_counter_ns()
            record["latency_ms"] = (record["response_received_ns"] - record["request_started_ns"]) / 1_000_000
            record["cost"] = self.budget.commit(reservation, cost=reported_cost, tokens=reported_tokens)
        return record
"""Wall-clock race runtime, shared by the MCP server and spectator view.

The fixed physics clock owns input application. A drive acknowledgement is sent
only after a physics step has actually used the submitted controls.
"""

from __future__ import annotations

import asyncio
import math
import time
import uuid
from dataclasses import dataclass, field
from typing import Any

from .sim import ACTIONS, DT, Simulation


def _percentile(values: list[float], fraction: float) -> float:
    if not values:
        return 0.0
    ordered = sorted(values)
    return ordered[min(len(ordered) - 1, math.ceil(fraction * len(ordered)) - 1)]


@dataclass
class _Race:
    race_id: str
    sim: Simulation
    seed: int
    deadline: float
    label: str
    started_ns: int
    status: str = "running"
    reason: str | None = None
    finished_ns: int | None = None
    last_command_seq: int = -1
    pending: tuple[dict[str, Any], asyncio.Future] | None = None
    task: asyncio.Task | None = None
    samples: list[dict[str, Any]] = field(default_factory=list)
    commands: list[dict[str, Any]] = field(default_factory=list)
    lateness_ms: list[float] = field(default_factory=list)
    last_observed_ns: int | None = None


class RaceRuntime:
    """One local race at a time; inference never advances the physics clock."""

    def __init__(self) -> None:
        self.current: _Race | None = None

    def start(self, seed: int = 0, deadline: float = 120.0, label: str = "") -> dict[str, Any]:
        if not math.isfinite(deadline) or deadline <= 0 or deadline > 86400:
            raise ValueError("deadline must be a positive number of seconds, at most 86400")
        if self.current is not None and self.current.status == "running":
            raise ValueError("A race is already running; finish it before starting another")
        race = _Race(uuid.uuid4().hex, Simulation(seed=seed, laps=3), seed, deadline, label, time.monotonic_ns())
        self.current = race
        self._sample(race, race.started_ns, 0.0)
        race.task = asyncio.create_task(self._run(race), name=f"race-{race.race_id}")
        return self.observe()

    def observe(self, race_id: str | None = None) -> dict[str, Any]:
        race = self._require_race(race_id)
        captured_ns = time.monotonic_ns()
        race.last_observed_ns = captured_ns
        return {**race.sim.observation(), "race_id": race.race_id, "observed_ns": captured_ns, "status": race.status}

    async def drive(
        self, race_id: str, action_id: str, observation_tick: int, command_seq: int
    ) -> dict[str, Any]:
        race = self._require_race(race_id)
        if race.status != "running":
            raise ValueError("This race has ended; its controls cannot be changed")
        if action_id not in ACTIONS:
            raise ValueError(f"Unknown action_id: {action_id}")
        if isinstance(command_seq, bool) or not isinstance(command_seq, int) or command_seq < 0:
            raise ValueError("command_seq must be a nonnegative integer")
        if command_seq <= race.last_command_seq:
            raise ValueError("Duplicate or out-of-order command_seq")
        if isinstance(observation_tick, bool) or not isinstance(observation_tick, int) or not 0 <= observation_tick <= race.sim.tick:
            raise ValueError("observation_tick must refer to an existing physics tick")
        if race.pending is not None:
            raise ValueError("A command is already waiting for its physics step")
        record = {
            "race_id": race_id, "action_id": action_id, "command_seq": command_seq,
            "observation_tick": observation_tick, "queued_ns": time.monotonic_ns(),
        }
        future = asyncio.get_running_loop().create_future()
        race.last_command_seq = command_seq
        race.pending = (record, future)
        # Shield leaves an accepted command in force even if its HTTP caller
        # disconnects before acknowledgement. No cancellation policy is a driver.
        return await asyncio.shield(future)

    def finish(self, race_id: str | None = None, reason: str = "cancelled") -> dict[str, Any]:
        race = self._require_race(race_id)
        if race.status == "running":
            self._end(race, reason)
            if race.task is not None:
                race.task.cancel()
        return self.result()

    def result(self) -> dict[str, Any]:
        race = self._require_race()
        timing = self._timing(race)
        summary = {**race.sim.summary(), "deadline": race.deadline, "realtime_valid": timing["infrastructure_valid"]}
        return {
            "race_id": race.race_id, "seed": race.seed, "label": race.label,
            "status": race.status, "reason": race.reason, "deadline": race.deadline,
            "started_ns": race.started_ns, "finished_ns": race.finished_ns,
            "summary": summary, "config": race.sim.config(),
            "track": race.sim.track.as_dict(), "timing": timing,
            "samples": list(race.samples), "commands": list(race.commands),
            "controls": list(race.commands), "realtime_valid": timing["infrastructure_valid"],
        }

    def state(self) -> dict[str, Any]:
        race = self.current
        if race is None:
            preview = Simulation(seed=0, laps=3)
            return {"status": "idle", "track": preview.track.as_dict(), "actions": ACTIONS, "config": preview.config()}
        now = time.monotonic_ns()
        # This read does not count as a model observation.
        observation = {**race.sim.observation(), "race_id": race.race_id, "status": race.status}
        return {
            "status": race.status, "race_id": race.race_id, "label": race.label,
            "reason": race.reason, "seed": race.seed, "deadline": race.deadline,
            "observation": observation, "track": race.sim.track.as_dict(), "actions": ACTIONS,
            "timing": self._timing(race), "command_count": len(race.commands),
            "waiting_for_reply": race.status == "running" and race.pending is None,
            "observation_age_ms": None if race.last_observed_ns is None else (now - race.last_observed_ns) / 1e6,
            "trail": [[s["kart"]["x"], s["kart"]["y"]] for s in race.samples[-600::3]],
        }

    async def close(self) -> None:
        if self.current is not None and self.current.status == "running":
            self.finish(reason="server_shutdown")
        task = self.current.task if self.current is not None else None
        if task is not None:
            await asyncio.gather(task, return_exceptions=True)

    def _require_race(self, race_id: str | None = None) -> _Race:
        if self.current is None:
            raise ValueError("No race has started")
        if race_id is not None and race_id != self.current.race_id:
            raise ValueError("Stale race_id; the command belongs to a different race")
        return self.current

