fn request(message:Value,race:&mut Option<Race>,outbox:&Outbox,session:&str)->Result<bool,String> {
    if message["session_id"].as_str()!=Some(session) {return Ok(false);}
    let identity=message["id"].clone();let method=message["method"].as_str().unwrap_or("");let args=&message["arguments"];
    let mut state=None;let mut terminal=false;let mut stopping=false;
    let result=(||->Result<Option<Payload>,String> {match method {
        "start"=> {
            if race.as_ref().map(|r|r.status=="running").unwrap_or(false) {return Err("A race is already running; finish it before starting another".into());}
            let deadline=args["deadline"].as_f64().unwrap_or(120.0);
            if !deadline.is_finite()||deadline<=0.0||deadline>86400.0 {return Err("deadline must be a positive number of seconds, at most 86400".into());}
            let sim=Simulation::from_fixture(&args["fixture"])?;
            if sim.tick!=0||sim.elapsed!=0.0||sim.finished {return Err("Live races must start at tick and elapsed zero".into());}
            let mut next=Race::new(sim,deadline,args["label"].as_str().unwrap_or("").into(),session)?;
            next.last_observed_ns=Some(monotonic_ns());let snapshot=next.snapshot(false);state=Some(snapshot.clone());
            *race=Some(next);Ok(Some(Payload::Observation(snapshot)))
        },
        "observe"=> {let race=required_race(race)?;race.require(args)?;race.last_observed_ns=Some(monotonic_ns());Ok(Some(Payload::Observation(race.snapshot(false))))},
        "drive"=> {
            let race=required_race(race)?;race.require(args)?;
            let action=args["action_id"].as_str().ok_or("action_id must be a string")?;
            if race.status!="running" {race.last_observed_ns=Some(monotonic_ns());return Ok(Some(Payload::Ended(json!({"race_id":race.race_id,
                "command_seq":args["command_seq"],"action_id":action,"applied":false,"reason":"race_already_ended"}),race.snapshot(false))));}
            if !sim::valid_action(action) {return Err(format!("Unknown action_id: {action}"));}
            let seq=args["command_seq"].as_u64().ok_or("command_seq must be a nonnegative integer")?;
            let tick=args["observation_tick"].as_u64().ok_or("observation_tick must refer to an existing physics tick")?;
            if tick>race.sim.tick {return Err("observation_tick must refer to an existing physics tick".into());}
            let command=Command {race_id:race.race_id.clone(),action_id:action.into(),observation_tick:tick,
                command_seq:seq,queued_ns:monotonic_ns(),applied_ns:None,applied_tick:None,reset_during_step:false};
            if race.sim.last_reset_tick.map(|t|tick<t).unwrap_or(false) {let rejected=Rejected {command,reason:"observation_before_rescue".into(),rejected_ns:monotonic_ns()};
                race.rejected.push(rejected.clone());race.last_observed_ns=Some(monotonic_ns());return Ok(Some(Payload::Rejection(rejected,race.snapshot(false))));}
            if race.last_command_seq.map(|last|seq<=last).unwrap_or(false) {return Err("Duplicate or out-of-order command_seq".into());}
            if race.pending.is_some() {return Err("A command is already waiting for its physics step".into());}
            race.pending=Some(Pending {identity:identity.clone(),command});Ok(None)
        },
        "finish"|"result"=> {
            let race=required_race(race)?;race.require(args)?;
            if method=="finish"&&race.status=="running" {race.end(args["reason"].as_str().unwrap_or("cancelled"),outbox)?;}
            let recording=race.recording()?;state=Some(recording.snapshot.clone());terminal=true;
