    match result {Ok(None)=>{},Ok(Some(value))=>outbox.reply(identity,Ok(value),state,terminal)?,Err(error)=>outbox.reply(identity,Err(error),None,false)?}
    Ok(stopping)
}

pub fn run(session:String,idle:Value)->Result<(),String> {
    let (tx,rx)=mpsc::sync_channel::<Value>(QUEUE_LIMIT);
    let reader_session=session.clone();
    thread::Builder::new().name("kart-ndjson-reader".into()).spawn(move|| {
        for line in io::stdin().lock().lines() {
            let value=match line {Ok(line)=>match serde_json::from_str::<Value>(&line) {Ok(value)=>value,Err(_)=>continue},Err(_)=>break};
            if value["session_id"].as_str()!=Some(reader_session.as_str()) {continue;}
            if tx.send(value).is_err() {return;}
        }
    }).map_err(|e|e.to_string())?;
    let (output_tx,output_rx)=mpsc::sync_channel::<Output>(QUEUE_LIMIT);
    let latest=Arc::new(Mutex::new(None::<Snapshot>));let failed=Arc::new(AtomicBool::new(false));
    let writer_latest=latest.clone();let writer_failed=failed.clone();let writer_session=session.clone();
    let writer=thread::Builder::new().name("kart-ndjson-writer".into()).spawn(move|| {
        let stdout=io::stdout();let mut writer=BufWriter::new(stdout.lock());
        loop {
            match output_rx.recv_timeout(Duration::from_millis(5)) {
                Ok(output)=>if write_output(&mut writer,&writer_session,output).is_err() {writer_failed.store(true,Ordering::Relaxed);break;},
                Err(mpsc::RecvTimeoutError::Disconnected)=>break,
                Err(mpsc::RecvTimeoutError::Timeout)=>{},
            }
            let snapshot=writer_latest.lock().unwrap().take();
            if let Some(snapshot)=snapshot {
                let state=json!({"type":"state","session_id":writer_session,"captured_ns":snapshot.captured_ns,"state":snapshot.state()});
                if serde_json::to_writer(&mut writer,&state).is_err()||writer.write_all(b"\n").is_err()||writer.flush().is_err() {
                    writer_failed.store(true,Ordering::Relaxed);break;
                }
            }
        }
    }).map_err(|e|e.to_string())?;
    let outbox=Outbox {tx:output_tx,latest,failed};
    outbox.tx.try_send(Output::Ready(json!({"type":"ready","pid":std::process::id(),"ready_ns":monotonic_ns(),"state":idle,
        "entrypoint":"mcpkart-rust-worker","clock_mode":CLOCK_MODE,"web_modules_loaded":[]}))).map_err(|e|e.to_string())?;
    let mut race:Option<Race>=None;
    let result=(||->Result<(),String> {loop {
        if outbox.failed.load(Ordering::Relaxed) {return Err("Worker output disconnected".into());}
        let wait=if let Some(race)=race.as_ref().filter(|r|r.status=="running") {
            let target=race.started_ns+((race.sim.tick+1)as f64*DT*1e9).round()as u64;
            let now=monotonic_ns();
            if now>=target {
                let current=race.sim.tick;
                let tick_result=race_tick(&mut race,&outbox);
                if let Err(error)=tick_result {if let Some(race)=race.as_mut() {race.end(&format!("runtime_error:{error}"),&outbox)?;}return Err(error);}
                let _=current;continue;
            }
            Duration::from_nanos(target-now)
        }else {Duration::from_millis(100)};
        match rx.recv_timeout(wait) {
            Ok(message)=>if request(message,&mut race,&outbox,&session)? {return Ok(());},
            Err(mpsc::RecvTimeoutError::Timeout)=>{},
            Err(mpsc::RecvTimeoutError::Disconnected)=> {if let Some(race)=race.as_mut().filter(|r|r.status=="running") {race.end("server_shutdown",&outbox)?;}return Ok(());},
        }
    }})();
    drop(outbox);let _=writer.join();result
}

fn race_tick(race:&mut Option<Race>,outbox:&Outbox)->Result<(),String> {required_race(race)?.tick(outbox)}
"}

