payload.input:
const results=await Promise.allSettled([
tools.exec_command({cmd:".venv/bin/python - <<'PY'
from pathlib import Path
import json
root=Path('artifacts/remote-clock-v1');base=root/'downloaded/remote-clock-v1'
r=json.loads((root/'model-results/jev-remote-navigation-v1/typesafe--jev-1.14--seed-0.json').read_text())
print({'summary':r['race']['summary'],'metrics':{k:r['metrics'].get(k) for k in ('cost_usd','request_count','request_errors','discarded_commands','api_latency_ms','observation_age_ms')},'timing':{k:r['race']['timing'][k] for k in ('max_lateness_ms','p95_lateness_ms','drift_ms')},'route':{k:r.get('route',{}).get(k) for k in ('model','provider','resolved_model')},'model':r.get('model'),'fingerprint':r['fingerprint'],'samples':len(r['race']['samples'])})
for name in ('docker-version.json','host-spectator.json','cgroup-after.json','linux-environment.json'):
 data=json.loads((base/name).read_text())
 if name=='docker-version.json':data={'server_version':data['Server']['Version']}
 elif name=='linux-environment.json':data={k:data.get(k) for k in ('fingerprint','runtime_info','api_key_present')}
 print({name:data})
PY",workdir:"/Users/atbaker/Projects/atbaker/mcpkart",max_output_tokens:3500}),
tools.write_stdin({session_id:19112,chars:"",yield_time_ms:1000,max_output_tokens:1800})
]);results.forEach((r,i)=>text({i,...r}));

